shacl_output:
ice:TorsionalVibrationShape a sh:NodeShape ;
    sh:targetNode ssp:MainPropeller ;
    sh:message "Simulation Readiness Check: Peak design torque Q_peak from torsional vibration analysis is missing." ;

    sh:sparql [
        sh:message "Propeller is missing Q_peak required for time-domain torsional vibration analysis." ;
        sh:select """
            PREFIX ssp: <https://w3id.org/mtl-requirements/ssp#>
            PREFIX ssn: <http://www.w3.org/ns/ssn/>

            SELECT $this
            WHERE {
                FILTER NOT EXISTS {
                    ssp:PeakPropellerTorque ssn:isPropertyOf $this .
                }
            }
        """
    ] .
